import Testing
@testable import IslandCore

private let plain = "public.utf8-plain-text"

@Test func secretTypesAreNeverRecorded() {
    for secret in [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ] {
        #expect(!ClipboardFilter.shouldRecord(types: [plain, secret], text: "hunter2"), "\(secret)")
        #expect(!ClipboardFilter.shouldRecord(types: [secret], text: nil), "\(secret)")
    }
}

@Test func ordinaryTextIsRecorded() {
    #expect(ClipboardFilter.shouldRecord(types: [plain], text: "hello"))
}

@Test func imagesAndFilesWithNoTextAreRecorded() {
    #expect(ClipboardFilter.shouldRecord(types: ["public.png"], text: nil))
    #expect(ClipboardFilter.shouldRecord(types: ["public.file-url"], text: nil))
}

@Test func hugeTextIsNotRecordedButTheLimitItselfIs() {
    #expect(ClipboardFilter.shouldRecord(types: [plain], text: String(repeating: "a", count: 1_000_000)))
    #expect(!ClipboardFilter.shouldRecord(types: [plain], text: String(repeating: "a", count: 1_000_001)))
}

@Test func blankTextIsNotRecorded() {
    #expect(!ClipboardFilter.shouldRecord(types: [plain], text: ""))
    #expect(!ClipboardFilter.shouldRecord(types: [plain], text: "  \n\t "))
}
